"""ORD_LINE renumbering migrated from Meridian CRM 4.2."""

from decimal import Decimal


def _numeric_line_no(value: object) -> Decimal:
    """Apply legacy numeric-context treatment for a missing/empty line number."""
    if value is None or value == "":
        return Decimal(0)
    return Decimal(str(value))


def renumber(lines: list[dict]) -> list[dict]:
    """Remove soft-deleted order lines and assign contiguous line numbers per order."""
    orders: dict[str, list[dict]] = {}

    for row in lines:
        if row.get("DEL_FLG", "") == "Y":
            continue

        order_id = str(row.get("ORD_ID", ""))
        orders.setdefault(order_id, []).append(row)

    result: list[dict] = []

    for order_id in sorted(orders):
        # Python's stable sort preserves input order for equal original LINE_NO values.
        ordered_lines = sorted(
            orders[order_id],
            key=lambda row: _numeric_line_no(row.get("LINE_NO", "")),
        )

        for new_line_no, row in enumerate(ordered_lines, start=1):
            migrated_row = dict(row)
            migrated_row["LINE_NO"] = new_line_no
            result.append(migrated_row)

    return result
